## 执行顺序

事件处理器会按插件优先级排序执行：

1. `CRITICAL (200)`
2. `HIGH (100)`
3. `NORMAL (50)`
4. `LOW (0)`

同优先级下，按注册先后顺序执行。

## 完整示例：背景网格插件

```ts
import {
  PluginPriority,
  PluginType,
  type TimelinePlugin,
} from "timeline-canvas";

interface GridPluginOptions {
  color?: string;
  spacing?: number;
  opacity?: number;
}

export function GridPlugin(
  userOptions: GridPluginOptions = {}
): TimelinePlugin {
  const options = {
    color: "#d0d7e2",
    spacing: 40,
    opacity: 0.5,
    ...userOptions,
  };

  return {
    metadata: {
      name: "grid-plugin",
      version: "1.0.0",
      description: "在背景层绘制辅助网格",
      type: PluginType.RENDER,
      priority: PluginPriority.NORMAL,
    },

    init(context) {
      context.api.setData("gridOptions", options);
    },

    activate(context) {
      context.api.registerRenderLayer({
        name: "grid-plugin-layer",
        position: "background",
        render(ctx, canvas) {
          const cfg = context.api.getData("gridOptions") as GridPluginOptions;
          if (!cfg) return;

          ctx.save();
          ctx.strokeStyle = cfg.color || "#d0d7e2";
          ctx.globalAlpha = cfg.opacity ?? 0.5;
          ctx.lineWidth = 1;

          const spacing = cfg.spacing || 40;
          for (let x = 0; x < canvas.width; x += spacing) {
            ctx.beginPath();
            ctx.moveTo(x, 0);
            ctx.lineTo(x, canvas.height);
            ctx.stroke();
          }

          ctx.restore();
        },
      });
    },

    deactivate(context) {
      context.api.unregisterRenderLayer("grid-plugin-layer");
    },
  };
}
```

